"""Generate trust/verify_readonly.sql (the DBA script) from db/verify_checks.sql, the single implementation of the
checks (PgSource.verify_readonly() runs the same file). `python db/build_verify.py` writes it; `--check` exits 1
when the committed file is stale."""

from __future__ import annotations

import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
CHECKS = HERE / "verify_checks.sql"
OUT = HERE.parent / "trust" / "verify_readonly.sql"
BS = chr(92)  # psql meta-commands start with a backslash

HEADER = "\n".join(
    [
        "-- GENERATED by db/build_verify.py from db/verify_checks.sql. Do not edit; run the generator.",
        "-- Read-only check script for the Ask-your-data login. It changes nothing. Run it AS the read-only login:",
        '--   psql "<connection string of the askdata_ro login>" -f verify_readonly.sql',
        "-- Exit status: 0 = every check is green; 3 = a check failed or could not run; anything else = connection",
        "-- problem. Each row: check | ok | detail. The INFO row is always ok; it reports what this login cannot be",
        "-- stopped from doing.",
        f"{BS}set ON_ERROR_STOP on",
        "",
    ]
)
FOOTER = "\n".join(
    [f"{BS}if :all_ok", f"{BS}else", "  SELECT 'verify_readonly: RED'::int;", f"{BS}endif", ""]
)


def build() -> str:
    checks = CHECKS.read_text(encoding="utf-8").strip().rstrip(";").strip() + "\n"
    gset = f"SELECT bool_and(COALESCE(ok, false)) AS all_ok FROM (\n{checks}) c {BS}gset\n"  # noqa: S608  # nosec
    return f"{HEADER}{checks};\n{gset}{FOOTER}"


def main(argv: list[str]) -> int:
    text = build()
    if "--check" in argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current.replace("\r\n", "\n") != text:
            sys.stderr.write("trust/verify_readonly.sql is stale: run python db/build_verify.py\n")
            return 1
        return 0
    OUT.write_text(text, encoding="utf-8", newline="\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
